<?php
 namespace QQWorld\Catalog\Helper\Product; class ProductList { const XML_PATH_LIST_MODE = 'catalog/frontend/list_mode'; const VIEW_MODE_LIST = 'list'; const VIEW_MODE_GRID = 'grid'; const DEFAULT_SORT_DIRECTION = 'asc'; protected $scopeConfig; protected $_defaultAvailableLimit = [10 => 10,20 => 20,50 => 50]; public function __construct( \QQWorld\Framework\App\Config\ScopeConfigInterface $scopeConfig ) { $this->scopeConfig = $scopeConfig; } public function getAvailableViewMode() { switch ($this->scopeConfig->getValue(self::XML_PATH_LIST_MODE, \QQWorld\Store\Model\ScopeInterface::SCOPE_STORE)) { case 'grid': $availableMode = ['grid' => __('Grid')]; break; case 'list': $availableMode = ['list' => __('List')]; break; case 'grid-list': $availableMode = ['grid' => __('Grid'), 'list' => __('List')]; break; case 'list-grid': $availableMode = ['list' => __('List'), 'grid' => __('Grid')]; break; default: $availableMode = null; break; } return $availableMode; } public function getDefaultViewMode($options = []) { if (empty($options)) { $options = $this->getAvailableViewMode(); } return current(array_keys($options)); } public function getDefaultSortField() { return $this->scopeConfig->getValue( \QQWorld\Catalog\Model\Config::XML_PATH_LIST_DEFAULT_SORT_BY, \QQWorld\Store\Model\ScopeInterface::SCOPE_STORE ); } public function getAvailableLimit($mode) { if (!in_array($mode, [self::VIEW_MODE_GRID, self::VIEW_MODE_LIST])) { return $this->_defaultAvailableLimit; } $perPageConfigKey = 'catalog/frontend/' . $mode . '_per_page_values'; $perPageValues = (string)$this->scopeConfig->getValue( $perPageConfigKey, \QQWorld\Store\Model\ScopeInterface::SCOPE_STORE ); $perPageValues = explode(',', $perPageValues); $perPageValues = array_combine($perPageValues, $perPageValues); if ($this->scopeConfig->isSetFlag( 'catalog/frontend/list_allow_all', \QQWorld\Store\Model\ScopeInterface::SCOPE_STORE )) { return ($perPageValues + ['all' => __('All')]); } else { return $perPageValues; } } public function getDefaultLimitPerPageValue($viewMode) { if ($viewMode == self::VIEW_MODE_LIST) { return $this->scopeConfig->getValue( 'catalog/frontend/list_per_page', \QQWorld\Store\Model\ScopeInterface::SCOPE_STORE ); } elseif ($viewMode == self::VIEW_MODE_GRID) { return $this->scopeConfig->getValue( 'catalog/frontend/grid_per_page', \QQWorld\Store\Model\ScopeInterface::SCOPE_STORE ); } return 0; } } 